            const Icon(Icons.stars_rounded, color: Color(0xFFDAA234), size: 40),
            const SizedBox(height: 8),
            const Text('Bonus kelimeler', style: TextStyle(fontSize: 23,
                fontWeight: FontWeight.w900)),
            const SizedBox(height: 8),
